"""
    Solve x = a^b % c
    :param base: a
    :param power: b
    :param mod: c
    :return: x
    """
def mod_pow(base: Any, power: Any, mod: Any) -> object {
    if (power < 0) {
        return -1;
    }
    base %= mod;
    result = 1;
    while (power > 0) {
        if (power & 1) {
            result = (result * base) % mod;
        }
        power = power >> 1;
        base = (base * base) % mod;
    }
    return result;
}

